/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0xFFFFFFFF); // CONSOLE_BACKGROUND_KEY
    e.text = px(0x000000FF); // DEFAULT_IDENTIFIER.fg
    e.caret = px(0x000000FF); // CARET_COLOR
    e.caret_row = px(0xFFFAE3FF); // CARET_ROW_COLOR
    e.line_number = px(0x999999FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0x999999FF); // LINE_NUMBERS_COLOR
    e.selection = px(0x5974ABFF); // SELECTION_BACKGROUND
    e.background_panel = px(0xF7F7F7FF); // DOCUMENTATION_COLOR
    e.search_result = px(0xFFFF00FF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0xE4E4FFFF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.matched_brace = px(0x99CCFFFF); // MATCHED_BRACE_ATTRIBUTES.bg
    e.indent_guide = px(0xE6E6E6FF); // INDENT_GUIDE
    e.error_effect = px(0xFF0000FF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0xEBC700FF); // WARNING_ATTRIBUTES.stripe
    e.weak_warning_effect = px(0xCCCCCCFF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0xFAEAE6FF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x2154A6FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0x868686FF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0xCF5B56FF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xEBC700FF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x008000FF); // DEFAULT_STRING.fg
    e.number = px(0x0000FFFF); // DEFAULT_NUMBER.fg
    e.keyword = px(0x000080FF); // DEFAULT_KEYWORD.fg
    e.constant = px(0x660E7AFF); // DEFAULT_CONSTANT.fg
    e.type_name = px(0x20999DFF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0x808000FF); // DEFAULT_METADATA.fg
    e.property = px(0x660E7AFF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0x404040FF); // mix(self:text, self:background, 0.25)
    e.comment = px(0x808080FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0x000080FF); // = keyword
    e.attribute = px(0x0000FFFF); // DEFAULT_ATTRIBUTE.fg
    e.invalid = px(0xFF0000FF); // WRONG_REFERENCES_ATTRIBUTES.fg
    // Kept at the measured value: variable, search_result_current.
    e
}
